INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7544212, 1207295, 137576, '<td valign="top">this was my top pick should have finished higher great shot</td>', 'this was my top pick should have finished higher great shot', '2017-11-13 04:16:05.000000', NULL, 0),
(7544215, 1207857, 52549, '<td valign="top">So perfect for the challenge. Congratulations!</td>', 'So perfect for the challenge. Congratulations!', '2017-11-13 05:38:21.000000', NULL, 0),
(7544216, 1207649, 52549, '<td valign="top">Excellent take on the challenge. Congrats on the ribbon, Jeb.</td>', 'Excellent take on the challenge. Congrats on the ribbon, Jeb.', '2017-11-13 05:39:10.000000', NULL, 0),
(7544217, 1207805, 52549, '<td valign="top">This is so good. Congrats on the HM, Penny.</td>', 'This is so good. Congrats on the HM, Penny.', '2017-11-13 05:39:52.000000', NULL, 0),
(7544218, 1207785, 52549, '<td valign="top">Well seen, lovely image.</td>', 'Well seen, lovely image.', '2017-11-13 05:40:54.000000', NULL, 0),
(7544234, 1207854, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting challenge that meets the challenge<br/> <br/>Quite a challenge this, to make something interesting from the everyday mundane that we take for granted, I think youve done well here though I do think it could be improved upon. Given the image here I like the graphic qualities of the clock face against the equally graphic roof. Because of this I dont think the left of the shot contributes anything at all in fact I would say it detracts. A portrait orientated crop with the clock in the bottom left corner would, I think, work much better?</td>', 'Hello from the critique club An interesting challenge that meets the challenge Quite a challenge this, to make something interesting from the everyday mundane that we take for granted, I think youve done well here though I do think it could be improved upon. Given the image here I like the graphic qualities of the clock face against the equally graphic roof. Because of this I dont think the left of the shot contributes anything at all in fact I would say it detracts. A portrait orientated crop with the clock in the bottom left corner would, I think, work much better?', '2017-11-13 06:09:43.000000', NULL, 0),
(7544237, 1207855, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge<br/> <br/>Lovely capture Ronnie, justifiably well rewarded. I like the pose with the bird proudly displaying his hard won meal, I particularly like the two small pots of colour that are his eyes. I can imagine in the right light his plumage looks resplendent, there is a hint of it even here. The composition is good, in fact I dont really need to talk about technicalities do I, because youve always got it well nailed. I would say its just about as ordinary as your excellent work could be, well done.</td>', 'Hello from the critique club An appealing image that meets the challenge Lovely capture Ronnie, justifiably well rewarded. I like the pose with the bird proudly displaying his hard won meal, I particularly like the two small pots of colour that are his eyes. I can imagine in the right light his plumage looks resplendent, there is a hint of it even here. The composition is good, in fact I dont really need to talk about technicalities do I, because youve always got it well nailed. I would say its just about as ordinary as your excellent work could be, well done.', '2017-11-13 06:18:46.000000', NULL, 0),
(7544238, 1207846, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge<br/> <br/>Youve managed to make an ordinary leaf take on a new dimension with this macro view of the structure and colours of the leaf. The blemishes take on a whole different look and feel and the whole lets your imagination turn it into other things. Its lovely to see both the delicate detail of the cellular and the strength in the supporting vein like structure, lovely Susan.</td>', 'Hello from the critique club An appealing image that meets the challenge Youve managed to make an ordinary leaf take on a new dimension with this macro view of the structure and colours of the leaf. The blemishes take on a whole different look and feel and the whole lets your imagination turn it into other things. Its lovely to see both the delicate detail of the cellular and the strength in the supporting vein like structure, lovely Susan.', '2017-11-13 06:25:07.000000', NULL, 0),
(7544239, 1207287, 23098, '<td valign="top">Great macro.</td>', 'Great macro.', '2017-11-13 07:14:34.000000', NULL, 0),
